import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from '../remotionShim';
// Load Google Font at module level
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const { fontFamily: interFamily } = loadInter();



export type MinimalChatProps = Record<string, any>;

const ChatBubble: React.FC<{
  text: string;
  sender: "me" | "them";
  index: number;
  delayFrames: number;
  fps: number;
  frame: number;
  primaryColor: string;
  secondaryColor: string;
  textColorMe: string;
  textColorThem: string;
}> = ({
  text,
  sender,
  index,
  delayFrames,
  fps,
  frame,
  primaryColor,
  secondaryColor,
  textColorMe,
  textColorThem,
}) => {
  // Give a small pause before the first message appears
  const initialDelayFrames = Math.round(0.3 * fps);
  const startFrame = initialDelayFrames + index * delayFrames;

  // Do not render the bubble until its start frame to maintain layout integrity
  if (frame < startFrame) {
    return null;
  }

  const isMe = sender === "me";

  // Physics-based animation for slide and scale
  const progress = spring({
    frame: frame - startFrame,
    fps,
    config: {
      damping: 15,
      stiffness: 110,
      mass: 0.8,
    },
  });

  const opacity = interpolate(progress, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const translateY = interpolate(progress, [0, 1], [50, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const scale = interpolate(progress, [0, 1], [0.95, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        alignSelf: isMe ? "flex-end" : "flex-start",
        backgroundColor: isMe ? primaryColor : secondaryColor,
        color: isMe ? textColorMe : textColorThem,
        padding: "24px 32px",
        borderRadius: "32px",
        borderBottomRightRadius: isMe ? "8px" : "32px",
        borderBottomLeftRadius: isMe ? "32px" : "8px",
        fontSize: "36px",
        fontFamily: interFamily,
        fontWeight: 400,
        maxWidth: "85%",
        lineHeight: 1.45,
        boxShadow: "0 12px 32px rgba(0, 0, 0, 0.04)",
        opacity,
        transform: `translateY(${translateY}px) scale(${scale})`,
        transformOrigin: isMe ? "bottom right" : "bottom left",
        transition: "none", // Strict rule: No CSS transitions
        willChange: "transform, opacity",
      }}
    >
      {text}
    </div>
  );
};

const MinimalChat: React.FC<MinimalChatProps> = ({
  backgroundColor = "#F9FAFB",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryColor = "#007AFF", // Classic iOS Blue
  secondaryColor = "#E5E5EA", // Classic iOS Gray
  textColorMe = "#FFFFFF",
  textColorThem = "#000000",
  delayBetweenMessages = 1.2,
  chatMessages = [
    { sender: "them", text: "Hey! Have you seen the new mockups?" },
    { sender: "me", text: "Yes! The team at Malloy Studio did an amazing job." },
    { sender: "them", text: "Agreed. The minimal style works perfectly." },
    { sender: "me", text: "I'll approve them now so we can move forward." },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const delayFrames = Math.round(delayBetweenMessages * fps);
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: width * 0.5,
            paddingTop: height * 0.15,
            display: "flex",
            flexDirection: "column",
            gap: "36px",
          }}
        >
          {chatMessages.map((msg, idx) => (
            <ChatBubble
              key={idx}
              index={idx}
              text={msg.text}
              sender={msg.sender as "me" | "them"}
              delayFrames={delayFrames}
              fps={fps}
              frame={frame}
              primaryColor={primaryColor}
              secondaryColor={secondaryColor}
              textColorMe={textColorMe}
              textColorThem={textColorThem}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MinimalChat;